namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Baguette", "Tomatoes", "Fresh basil", "Garlic", "Olive oil", "Balsamic vinegar"],
            Steps = ["Slice and toast the baguette.", "Dice tomatoes, mix with basil, garlic, and olive oil.", "Spoon mixture onto toast and drizzle with balsamic."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Button mushrooms", "Cream cheese", "Garlic", "Breadcrumbs", "Parmesan"],
            Steps = ["Remove mushroom stems and hollow caps.", "Mix cream cheese, garlic, breadcrumbs, and parmesan.", "Fill caps and bake at 375°F for 20 minutes."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper"],
            Steps = ["Cook spaghetti al dente.", "Fry pancetta until crispy.", "Whisk eggs with parmesan.", "Toss hot pasta with pancetta, then stir in egg mixture off heat."],
            AverageRating = 4.8, RatingCount = 25
        },
        new()
        {
            Id = 4, Title = "Chicken Tikka Masala", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Chicken breast", "Yogurt", "Tikka spice mix", "Tomato sauce", "Cream", "Rice"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken pieces.", "Simmer tomato sauce with cream, add chicken.", "Serve over basmati rice."],
            AverageRating = 4.7, RatingCount = 19
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour"],
            Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold in chocolate mixture and flour.", "Bake at 425°F for 12 minutes."],
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 6, Title = "Tiramisu", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Ladyfingers", "Mascarpone", "Espresso", "Cocoa powder", "Eggs", "Sugar"],
            Steps = ["Dip ladyfingers in espresso.", "Beat egg yolks with sugar, fold in mascarpone.", "Layer dipped ladyfingers and cream.", "Refrigerate 4 hours, dust with cocoa."],
            AverageRating = 4.6, RatingCount = 15
        },
        new()
        {
            Id = 7, Title = "Mango Smoothie", Category = "Beverages", CategorySlug = "beverages",
            Ingredients = ["Mango", "Yogurt", "Honey", "Ice"],
            Steps = ["Peel and chop mango.", "Blend all ingredients until smooth.", "Serve immediately."],
            AverageRating = 4.3, RatingCount = 10
        },
        new()
        {
            Id = 8, Title = "Sourdough Bread", Category = "Baking", CategorySlug = "baking",
            Ingredients = ["Bread flour", "Water", "Sourdough starter", "Salt"],
            Steps = ["Mix flour, water, and starter. Rest 30 minutes.", "Add salt and fold dough every 30 min for 2 hours.", "Shape and cold-proof overnight.", "Bake in Dutch oven at 450°F for 40 minutes."],
            AverageRating = 4.4, RatingCount = 22
        },
        new()
        {
            Id = 9, Title = "Vegetable Stir Fry", Category = "Vegetarian", CategorySlug = "vegetarian",
            Ingredients = ["Broccoli", "Bell peppers", "Snap peas", "Soy sauce", "Ginger", "Garlic", "Sesame oil"],
            Steps = ["Chop all vegetables.", "Heat sesame oil in a wok over high heat.", "Stir fry vegetables 3-4 minutes.", "Add soy sauce, ginger, and garlic. Toss and serve."],
            AverageRating = 4.1, RatingCount = 14
        }
    ];

    private int _nextId = 10;

    public List<Recipe> GetByCategory(string categorySlug)
    {
        return _recipes.Where(r => r.CategorySlug == categorySlug).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public List<Recipe> GetAll()
    {
        return _recipes.ToList();
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalRating + stars) / recipe.RatingCount;
        }
    }
}

