@page "/recipes/{categorySlug?}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes - RecipeShare</PageTitle>

@if (string.IsNullOrEmpty(CategorySlug))
{
    <h1>All Recipes</h1>
    <p>Select a category or browse all recipes below.</p>

    @foreach (var group in recipes.GroupBy(r => r.Category))
    {
        <h3 class="mt-4">@group.Key</h3>
        <div class="list-group mb-3">
            @foreach (var recipe in group)
            {
                <a href="recipe/@recipe.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                    @recipe.Title
                    <span class="badge bg-warning text-dark">⭐ @recipe.AverageRating.ToString("F1")</span>
                </a>
            }
        </div>
    }
}
else
{
    <h1>@categoryName Recipes</h1>
    <a href="recipes" class="btn btn-sm btn-outline-secondary mb-3">← All Categories</a>

    @if (recipes.Count == 0)
    {
        <p class="text-muted">No recipes found in this category.</p>
    }
    else
    {
        <div class="list-group">
            @foreach (var recipe in recipes)
            {
                <a href="recipe/@recipe.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                    @recipe.Title
                    <span class="badge bg-warning text-dark">⭐ @recipe.AverageRating.ToString("F1")</span>
                </a>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategorySlug { get; set; }

    private List<Recipe> recipes = [];
    private string categoryName = "";

    protected override void OnInitialized()
    {
        if (string.IsNullOrEmpty(CategorySlug))
        {
            recipes = RecipeService.GetAll();
        }
        else
        {
            recipes = RecipeService.GetByCategory(CategorySlug);
            categoryName = recipes.FirstOrDefault()?.Category ?? CategorySlug;
        }
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="recipes" class="btn btn-primary">Browse Recipes</a>
}
else
{
    <a href="recipes/@recipe.CategorySlug" class="btn btn-sm btn-outline-secondary mb-3">← Back to @recipe.Category</a>

    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: @recipe.Category</p>

    <div class="mb-4">
        <StarRating RecipeId="@recipe.Id" CurrentRating="@recipe.AverageRating" RatingCount="@recipe.RatingCount" />
    </div>

    <h3>Ingredients</h3>
    <ul class="list-group list-group-flush mb-4">
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in recipe.Steps)
        {
            <li class="list-group-item">@step</li>
        }
    </ol>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    <span>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" style="cursor:pointer; font-size:1.5rem; color:@(star <= selectedRating ? "#ffc107" : "#ddd")"
                  @onclick="() => Rate(star)"
                  title="Rate @star star@(star > 1 ? "s" : "")">★</span>
        }
    </span>
    <span class="text-muted small">
        @CurrentRating.ToString("F1") avg (@RatingCount ratings)
        @if (hasRated)
        {
            <span class="text-success ms-2">✓ Thanks for rating!</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int selectedRating;
    private bool hasRated;

    private void Rate(int stars)
    {
        if (hasRated) return;

        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }

        hasRated = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added successfully.</p>
        <a href="recipe/@submittedId" class="btn btn-primary">View Recipe</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="@this" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="title" placeholder="e.g., Grandma's Apple Pie" />
            @if (showValidation && string.IsNullOrWhiteSpace(title))
            {
                <div class="text-danger small">Title is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="category">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
                <option value="beverages">Beverages</option>
                <option value="baking">Baking</option>
                <option value="vegetarian">Vegetarian</option>
            </InputSelect>
            @if (showValidation && string.IsNullOrWhiteSpace(category))
            {
                <div class="text-danger small">Category is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="ingredients"
                           placeholder="One ingredient per line" />
            @if (showValidation && string.IsNullOrWhiteSpace(ingredients))
            {
                <div class="text-danger small">At least one ingredient is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="steps"
                           placeholder="One step per line" />
            @if (showValidation && string.IsNullOrWhiteSpace(steps))
            {
                <div class="text-danger small">At least one step is required.</div>
            }
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private string title = "";
    private string category = "";
    private string ingredients = "";
    private string steps = "";
    private bool submitted;
    private bool showValidation;
    private int submittedId;

    private static readonly Dictionary<string, string> CategoryNames = new()
    {
        ["appetizers"] = "Appetizers",
        ["main-courses"] = "Main Courses",
        ["desserts"] = "Desserts",
        ["beverages"] = "Beverages",
        ["baking"] = "Baking",
        ["vegetarian"] = "Vegetarian"
    };

    private void HandleSubmit()
    {
        showValidation = true;

        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category) ||
            string.IsNullOrWhiteSpace(ingredients) || string.IsNullOrWhiteSpace(steps))
        {
            return;
        }

        var recipe = new Recipe
        {
            Title = title.Trim(),
            Category = CategoryNames.GetValueOrDefault(category, category),
            CategorySlug = category,
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        submittedId = recipe.Id;
        submitted = true;
    }

    private void Reset()
    {
        title = "";
        category = "";
        ingredients = "";
        steps = "";
        submitted = false;
        showValidation = false;
    }
}

